function articleCopy(locale:LocalizedLocale,slug:ArticleSlug){
  return locale==="ru"?ARTICLES_RU[slug]:locale==="uk"?ARTICLES_UK[slug]:ARTICLES_ES[slug];
}

function metadataCopy(locale:LocalizedLocale,slug:LocalizedInfoSlug){
  if(slug==="guides"){
    const copy=CHROME_COPY[locale];
    return {title:copy.guideDirectoryTitle,description:copy.guideDirectoryDescription,type:"website" as const};
  }
  if(slug==="api-docs"){
    if(locale==="ru")return {title:"API анализа текста: документация и примеры",description:"Документация публичного JSON API для частотности слов, плотности ключей, N-грамм, Bag of Words, TF-IDF, сходства и сравнения текстов.",type:"article" as const};
    if(locale==="uk")return {title:"API аналізу тексту: документація та приклади",description:"Документація публічного JSON API для частотності слів, щільності ключів, N-грам, Bag of Words, TF-IDF, подібності й порівняння текстів.",type:"article" as const};
    return {title:"API de análisis de texto: documentación y ejemplos",description:"Documentación de la API JSON pública para frecuencia, densidad, N-gramas, Bag of Words, TF-IDF, similitud y comparación de textos.",type:"article" as const};
  }
  if(slug==="cli"){
    if(locale==="ru")return {title:"CLI и MCP для анализа текста: npm и AI-агенты",description:"Установите textanalysis-tools из npm, запускайте восемь CLI-команд и подключайте локальный MCP-сервер к AI-агентам.",type:"article" as const};
    if(locale==="uk")return {title:"CLI та MCP для аналізу тексту: npm і AI-агенти",description:"Встановіть textanalysis-tools із npm, запускайте вісім CLI-команд і підключайте локальний MCP-сервер до AI-агентів.",type:"article" as const};
    return {title:"CLI y MCP de análisis de texto: npm y agentes de IA",description:"Instala textanalysis-tools desde npm, ejecuta ocho comandos CLI y conecta el servidor MCP local a agentes de IA.",type:"article" as const};
  }
  if(slug==="agents"){
    const copy=AGENT_COPY[locale];
    return {title:copy.title,description:copy.description,type:"article" as const};
  }
  const copy=articleCopy(locale,slug);
  return {title:copy.title,description:copy.description,type:"article" as const};
}

export function isLocalizedInfoSlug(value:string):value is LocalizedInfoSlug{
  return (LOCALIZED_INFO_SLUGS as readonly string[]).includes(value);
}

export function localizedInfoMetadata(locale:LocalizedLocale,slug:LocalizedInfoSlug):Metadata{
  const copy=metadataCopy(locale,slug);
  return localizedMetadata({locale,path:`/${slug}`,title:copy.title,description:copy.description,type:copy.type});
}

function GuidesDirectory({locale}:{locale:LocalizedLocale}){
  const copy=CHROME_COPY[locale];
  const names=GUIDE_NAMES[locale];
  const descriptions=locale==="ru"
    ?["Количество, проценты, нормализация и токенизация.","Точные фразы, A/B-сравнение и отсутствие идеального процента.","Векторы частот, признаки и ограничения модели.","Разреженные счётчики и обученные семантические векторы.","Нормированный TF, сглаженный IDF и влияние корпуса.","Векторная формула, вклад терминов и интерпретация оценки.","Униграммы, биграммы, триграммы и оконные знаменатели.","Нормализованные изменения словаря между A и B."]
    :locale==="uk"
      ?["Кількість, відсотки, нормалізація й токенізація.","Точні фрази, A/B-порівняння та відсутність ідеального відсотка.","Вектори частот, ознаки й обмеження моделі.","Розріджені лічильники й навчені семантичні вектори.","Нормований TF, згладжений IDF і вплив корпусу.","Векторна формула, внесок термінів і тлумачення оцінки.","Уніграми, біграми, триграми та віконні знаменники.","Нормалізовані зміни словника між A і B."]
      :["Cantidad, porcentajes, normalización y tokenización.","Frases exactas, comparación A/B y ausencia de un porcentaje ideal.","Vectores de frecuencia, características y límites del modelo.","Contadores dispersos y vectores semánticos entrenados.","TF normalizado, IDF suavizado e influencia del corpus.","Fórmula vectorial, contribución e interpretación de la puntuación.","Unigramas, bigramas, trigramas y denominadores de ventana.","Cambios normalizados de vocabulario entre A y B."];
  const schema={"@context":"https://schema.org","@type":"CollectionPage",name:copy.guideDirectoryTitle,description:copy.guideDirectoryDescription,inLanguage:locale,url:`${SITE_URL}${localizedPath(locale,"/guides")}`,mainEntity:{"@type":"ItemList",itemListElement:GUIDE_PATHS.map((path,index)=>({"@type":"ListItem",position:index+1,name:names[index],url:`${SITE_URL}${localizedPath(locale,path)}`}))}};
  return <main className="tool-page">
    <script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify(schema)}}/>
    <SiteHeader locale={locale} active="guide" languagePaths={languagePaths("/guides")}/>
    <section className="tools-directory-hero"><nav className="breadcrumbs" aria-label={copy.breadcrumb}><Link href={localizedPath(locale,"/")}>{copy.home}</Link><span>/</span><span>{copy.guides}</span></nav><p className="eyebrow">{copy.guideEye}</p><h1>{copy.guideDirectoryTitle}</h1><p>{copy.guideIntro}</p></section>
    <section className="tools-directory learning-directory guides-directory" aria-labelledby="all-localized-guides"><div className="directory-heading"><h2 id="all-localized-guides">{copy.guideHeading}</h2></div><div className="learning-grid">{GUIDE_PATHS.map((path,index)=><Link href={localizedPath(locale,path)} key={path}><span>{index===3?"NLP":copy.guide}</span><h3>{names[index]}</h3><p>{descriptions[index]}</p><strong>{copy.readGuide} →</strong></Link>)}</div></section>
    <section className="tools-directory planned-tools"><div className="planned-grid developer-grid"><Link href={localizedPath(locale,"/tools")}><span>{copy.webTools}</span><h3>{copy.tools}</h3></Link><Link href={localizedPath(locale,"/api-docs")}><span>JSON · OPENAPI</span><h3>{copy.api}</h3></Link><Link href={localizedPath(locale,"/cli")}><span>NPM · MIT</span><h3>{copy.cli}</h3></Link></div></section>
    <SiteFooter locale={locale}/>
  </main>;
}

